import { useEffect, useState } from "react";
import { QrCode, Download } from "lucide-react";
import { getMyQrBlob, downloadMyQr } from "../../api/ReferralApi";
import { Card, PrimaryButton, SecondaryButton } from "./ReferralUi";

// QR preview + print-quality downloads. The image is generated by the server; we fetch it
// with the caller's own session token (an <img src> could not send the bearer header).
const ReferralQrCard = ({ role, companyId, code, inactive = false }) => {
  const [previewUrl, setPreviewUrl] = useState(null);
  const [previewFailed, setPreviewFailed] = useState(false);
  const [busy, setBusy] = useState(null);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!code) return undefined;
    let cancelled = false;
    let objectUrl = null;
    setPreviewFailed(false);
    getMyQrBlob(role, companyId, { format: "png", size: 512 })
      .then(({ blob }) => {
        if (cancelled) return;
        objectUrl = URL.createObjectURL(blob);
        setPreviewUrl(objectUrl);
      })
      .catch(() => {
        if (!cancelled) setPreviewFailed(true);
      });
    return () => {
      cancelled = true;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [role, companyId, code]);

  const download = async (format) => {
    setBusy(format);
    setError("");
    try {
      await downloadMyQr(role, companyId, { format, size: 1024 });
    } catch (err) {
      setError(err?.message || "Could not download the QR code. Please try again.");
    } finally {
      setBusy(null);
    }
  };

  return (
    <Card title="Your QR code" icon={<QrCode className="h-4 w-4" />}>
      <div className="flex flex-col items-center gap-4 sm:flex-row sm:items-start">
        <div
          className={`flex h-44 w-44 shrink-0 items-center justify-center rounded-xl border border-gray-100 bg-white p-2 ${
            inactive ? "opacity-50" : ""
          }`}
        >
          {previewUrl ? (
            <img src={previewUrl} alt="Your referral QR code" className="h-full w-full object-contain" />
          ) : previewFailed ? (
            <p className="px-2 text-center text-xs text-gray-400">QR preview unavailable</p>
          ) : (
            <div className="h-full w-full animate-pulse rounded-lg bg-gray-100" />
          )}
        </div>
        <div className="flex w-full flex-col gap-2">
          <p className="text-xs text-gray-600">
            Print it on your desk, letterhead or visiting card. Anyone who scans it lands on your
            referral page.
          </p>
          <div className="flex flex-wrap gap-2">
            <PrimaryButton onClick={() => download("png")} disabled={!code || busy !== null}>
              <Download className="h-4 w-4" />
              {busy === "png" ? "Preparing…" : "PNG (print quality)"}
            </PrimaryButton>
            <SecondaryButton onClick={() => download("svg")} disabled={!code || busy !== null}>
              <Download className="h-4 w-4" />
              {busy === "svg" ? "Preparing…" : "SVG"}
            </SecondaryButton>
          </div>
          {error && <p className="text-xs text-red-600">{error}</p>}
        </div>
      </div>
    </Card>
  );
};

export default ReferralQrCard;
